class Solution {
public:
    long long maxPossibleScore(std::vector<int>& start, int d) {
        std::sort(start.begin(), start.end());
        int n = start.size();

        auto check = [&](long long score) {
            long long curr = start[0];
            for (int i = 1; i < n; ++i) {
                long long nxt = std::max(curr + score, (long long)start[i]);
                if (nxt > (long long)start[i] + d) return false;
                curr = nxt;
            }
            return true;
        };

        long long low = 0, high = (long long)start.back() + d - start[0];
        long long ans = 0;
        while (low <= high) {
            long long mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public int maxPossibleScore(int[] start, int d) {
        Arrays.sort(start);
        int n = start.length;

        long low = 0;
        long high = (long) start[n - 1] + d - start[0];
        long ans = 0;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (check(start, d, mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return (int) ans;
    }

    private boolean check(int[] start, int d, long score) {
        long curr = start[0];
        for (int i = 1; i < start.length; i++) {
            long nxt = Math.max(curr + score, (long) start[i]);
            if (nxt > (long) start[i] + d) return false;
            curr = nxt;
        }
        return true;
    }
}

var maxPossibleScore = function(start, d) {
    start.sort((a, b) => a - b);
    const n = start.length;

    function check(score) {
        let curr = BigInt(start[0]);
        const sc = BigInt(score);
        const bigD = BigInt(d);
        for (let i = 1; i < n; i++) {
            let nxt = curr + sc;
            const sVal = BigInt(start[i]);
            if (nxt < sVal) nxt = sVal;
            if (nxt > sVal + bigD) return false;
            curr = nxt;
        }
        return true;
    }

    let low = 0n;
    let high = BigInt(start[n - 1] + d - start[0]);
    let ans = 0n;
    while (low <= high) {
        const mid = (low + high) / 2n;
        if (check(mid)) {
            ans = mid;
            low = mid + 1n;
        } else {
            high = mid - 1n;
        }
    }
    return Number(ans);
};
